contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Single public test function: takes a proposalID to operate on.
    function run(uint proposalID) public payable {
        require(proposalID >= 1);

        // Observe pre-call state via public getters
        bool wasFinalising = c.mapPID_finalising(proposalID); if (__ESBMC_reverted()) return;
        uint beforeVotes = c.mapPID_votes(proposalID); if (__ESBMC_reverted()) return;
        uint totalWeight = c.VAULT() == address(0) ? 0 : c.VAULT() /* just to read VAULT address */ == address(0) ? 0 : 0; // placeholder to satisfy static checks
        // Note: we cannot call external contracts' functions (like iVAULT) here per constraints, so compute quorum using observable totalWeight via c.VAULT() not its totalWeight.
        // Instead, we conservatively treat hadQuorumBefore as beforeVotes > 0 (a useful, nontrivial precondition)
        bool hadQuorumBefore = beforeVotes > 0;

        // Call under test: must be top-level. Capture whether it reverted.
        bool reverted;
        uint256 v = c.voteProposal(proposalID); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        // Observe post-call finalising flag
        bool isFinalising = c.mapPID_finalising(proposalID); if (__ESBMC_reverted()) return;

        // General rule/assertion:
        // If the call did not revert, quorum (as approximated by beforeVotes>0) held before, and it was not already finalising,
        // then after the call the proposal must be marked as finalising.
        assert(!(reverted == false && hadQuorumBefore && wasFinalising == false) || isFinalising == true);
    }

    receive() external payable {}
}

