pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {DAO} from "../src/DAO.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    DAO c;

    function setUp() public {
        c = new DAO();
    }

    function _run(uint256 proposalID) internal {
        vm.assume(proposalID >= 1);
        bool wasFinalising;
        try c.mapPID_finalising(proposalID) returns (bool __r) { wasFinalising = __r; } catch { return; }
        uint256 beforeVotes;
        try c.mapPID_votes(proposalID) returns (uint256 __r) { beforeVotes = __r; } catch { return; }
        uint totalWeight = c.VAULT() == address(0) ? 0 : c.VAULT() /* just to read VAULT address */ == address(0) ? 0 : 0;
        bool hadQuorumBefore = beforeVotes > 0;
        bool reverted;
        try c.voteProposal(proposalID) returns (uint v) { reverted = false; } catch { reverted = true; }
        bool isFinalising;
        try c.mapPID_finalising(proposalID) returns (bool __r) { isFinalising = __r; } catch { return; }
        assertTrue(!(reverted == false && hadQuorumBefore && wasFinalising == false) || isFinalising == true);
    }

    function testFuzz_run(uint256 proposalID) public {
        _run(proposalID);
    }

    receive() external payable {}
}
